set-variable.value:
@{
    var jwt = (Jwt)context.Variables["contoso.validatedCallerJwt"];
    string[] scopes;
    string[] identityTypes;
    if (!jwt.Claims.TryGetValue("scp", out scopes) || scopes == null || scopes.Length != 1 || scopes[0] == null) return false;
    if (jwt.Claims.TryGetValue("idtyp", out identityTypes)
      && (identityTypes == null || identityTypes.Length != 1 || identityTypes[0] == "app")) return false;
    return scopes[0].Split(' ').Contains("{{contoso-delegated-scope}}");
  }

@{
    var jwt = (Jwt)context.Variables["contoso.validatedCallerJwt"];
    string[] values;
    var clientId = "";
    if (jwt.Claims.TryGetValue("azp", out values)) {
      if (values == null || values.Length != 1 || values[0] == null) return false;
      clientId = values[0].ToLowerInvariant();
      string[] legacyClientIds;
      if (jwt.Claims.TryGetValue("appid", out legacyClientIds)
        && (legacyClientIds == null || legacyClientIds.Length != 1 || legacyClientIds[0] == null || legacyClientIds[0].ToLowerInvariant() != clientId)) return false;
    }
    else if (jwt.Claims.TryGetValue("appid", out values) && values != null && values.Length == 1 && values[0] != null) clientId = values[0].ToLowerInvariant();
    string[] roles;
    string[] identityTypes;
    return clientId.Length == 36
      && Regex.IsMatch(clientId, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")
      && clientId != "00000000-0000-0000-0000-000000000000"
      && !(bool)context.Variables["contoso.callerDelegated"]
      && !jwt.Claims.ContainsKey("scp")
      && jwt.Claims.TryGetValue("idtyp", out identityTypes)
      && identityTypes != null && identityTypes.Length == 1 && identityTypes[0] == "app"
      && jwt.Claims.TryGetValue("roles", out roles)
      && roles != null && roles.Contains("Portal.Invoke")
      && "{{contoso-portal-client-ids}}".Split(',').Contains(clientId);
  }
